import { OMD, ParserExit, getProgramName, parseRequiredStringOptions, toPythonRepr } from './lib/index.mjs';

const TEST6_OPTIONS = [
  { flag: '--a', dest: 'a', metavar: 'A', required: true },
  { flag: '--b', dest: 'b', metavar: 'B', required: true },
  { flag: '--c', dest: 'c', metavar: 'C', required: true },
];

export function main(argv = process.argv.slice(2)) {
  const args = parseRequiredStringOptions(argv, {
    prog: getProgramName(process.argv[1]),
    options: TEST6_OPTIONS,
  });

  const omd = new OMD();
  printLine(toPythonRepr(omd));
  omd.add(args.a, args.b);
  printLine(toPythonRepr(omd));
  omd.add(args.a, args.c);
  printLine(toPythonRepr(omd));
  printLine(toPythonRepr(omd.getlist(args.a)));
  printLine(toPythonRepr(omd.keys()));
  printLine(toPythonRepr(omd.items()));
}

function printLine(value) {
  process.stdout.write(`${value}\n`);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof ParserExit) {
    error.write();
    process.exit(error.code);
  }

  throw error;
}

import { toPythonRepr } from '../format/pythonRepr.mjs';

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const LONG_HELP_TOKENS = new Set(['--h', '--he', '--hel', '--help']);
const LONG_HELP_WITH_VALUE_PREFIXES = ['--h=', '--he=', '--hel=', '--help='];

export class ParserExit extends Error {
  constructor(code, output, streamName) {
    super(output.trimEnd());
    this.name = 'ParserExit';
    this.code = code;
    this.output = output;
    this.streamName = streamName;
  }

  write() {
    const stream = this.streamName === 'stdout' ? process.stdout : process.stderr;
    stream.write(this.output);
  }
}

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test6.mjs';
  }

  const normalizedPath = scriptPath.replace(/\\/g, '/');
  const parts = normalizedPath.split('/');
  return parts[parts.length - 1] || scriptPath;
}

export function formatUsage(prog, options) {
  const optionSummary = options.map((option) => `${option.flag} ${option.metavar}`).join(' ');
  return `usage: ${prog} [-h] ${optionSummary}`;
}

export function formatHelp(prog, options) {
  const optionLines = options.map((option) => `  ${option.flag} ${option.metavar}`).join('\n');
  return `${formatUsage(prog, options)}\n\noptions:\n  -h, --help  show this help message and exit\n${optionLines}\n`;
}

export function parseRequiredStringOptions(argv, config) {
  const { prog, options } = config;
  const optionsByFlag = new Map(options.map((option) => [option.flag, option]));
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('-h=')) {
      throw createErrorExit(prog, options, `argument -h/--help: ignored explicit argument ${toPythonRepr(token.slice(3))}`);
    }

    if (LONG_HELP_WITH_VALUE_PREFIXES.some((prefix) => token.startsWith(prefix))) {
      const argument = token.slice(token.indexOf('=') + 1);
      throw createErrorExit(prog, options, `argument -h/--help: ignored explicit argument ${toPythonRepr(argument)}`);
    }

    if (isShortHelpToken(token) || LONG_HELP_TOKENS.has(token)) {
      throw new ParserExit(0, formatHelp(prog, options), 'stdout');
    }

    if (token.startsWith('--') && token.includes('=')) {
      const equalsIndex = token.indexOf('=');
      const flag = token.slice(0, equalsIndex);
      const value = token.slice(equalsIndex + 1);
      const option = optionsByFlag.get(flag);

      if (option) {
        values[option.dest] = value;
        continue;
      }

      extras.push(token);
      continue;
    }

    const option = optionsByFlag.get(token);

    if (option) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || isOptionLike(nextToken)) {
        throw createErrorExit(prog, options, `argument ${option.flag}: expected one argument`);
      }

      values[option.dest] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missingFlags = options
    .filter((option) => option.required && !Object.prototype.hasOwnProperty.call(values, option.dest))
    .map((option) => option.flag);

  if (missingFlags.length > 0) {
    throw createErrorExit(prog, options, `the following arguments are required: ${missingFlags.join(', ')}`);
  }

  if (extras.length > 0) {
    throw createErrorExit(prog, options, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

function createErrorExit(prog, options, message) {
  const output = `${formatUsage(prog, options)}\n${prog}: error: ${message}\n`;
  return new ParserExit(2, output, 'stderr');
}

function isShortHelpToken(token) {
  return token.length >= 2 && token[0] === '-' && token[1] === 'h' && !token.startsWith('-h=');
}

function isOptionLike(token) {
  if (!token || token === '-' || !token.startsWith('-')) {
    return false;
  }

  return !NEGATIVE_NUMBER_PATTERN.test(token);
}

export class PythonTuple {
  constructor(items) {
    this.items = [...items];
  }

  toPythonRepr() {
    if (this.items.length === 1) {
      return `(${toPythonRepr(this.items[0])},)`;
    }

    return `(${this.items.map((item) => toPythonRepr(item)).join(', ')})`;
  }
}

export function tuple(...items) {
  return new PythonTuple(items);
}

export function toPythonRepr(value) {
  if (value && typeof value.toPythonRepr === 'function') {
    return value.toPythonRepr();
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null || value === undefined) {
    return 'None';
  }

  return String(value);
}

function formatPythonString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let result = quote;

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      result += '\\\\';
      continue;
    }

    if (char === quote) {
      result += `\\${quote}`;
      continue;
    }

    if (char === '\t') {
      result += '\\t';
      continue;
    }

    if (char === '\n') {
      result += '\\n';
      continue;
    }

    if (char === '\r') {
      result += '\\r';
      continue;
    }

    if ((codePoint >= 0x00 && codePoint <= 0x1f) || (codePoint >= 0x7f && codePoint <= 0x9f)) {
      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      continue;
    }

    result += char;
  }

  result += quote;
  return result;
}

import { toPythonRepr, tuple } from '../format/pythonRepr.mjs';

export class OrderedMultiDict {
  constructor() {
    this.entryList = [];
    this.keyOrder = [];
    this.valuesByKey = new Map();
  }

  add(key, value) {
    if (!this.valuesByKey.has(key)) {
      this.valuesByKey.set(key, []);
      this.keyOrder.push(key);
    }

    this.valuesByKey.get(key).push(value);
    this.entryList.push([key, value]);
  }

  getlist(key) {
    const values = this.valuesByKey.get(key);
    return values ? [...values] : [];
  }

  keys() {
    return [...this.keyOrder];
  }

  items() {
    return this.keyOrder.map((key) => {
      const values = this.valuesByKey.get(key);
      return tuple(key, values[values.length - 1]);
    });
  }

  toPythonRepr() {
    const allPairs = this.entryList.map(([key, value]) => tuple(key, value));
    return `OrderedMultiDict(${toPythonRepr(allPairs)})`;
  }

  toString() {
    return this.toPythonRepr();
  }
}

export { OrderedMultiDict as OMD };
